import java.io.*;
import java.net.*;
import java.sql.*;
import java.util.regex.*;
import javax.servlet.*;
import javax.servlet.http.*;

public class ReportServlet extends HttpServlet {
    private static final Pattern SAFE_ID = Pattern.compile("^[A-Za-z0-9_-]+$");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String reportId = req.getParameter("id");
        String format = req.getParameter("format");

        if (reportId == null || reportId.isEmpty()) {
            resp.sendError(400, "Missing report id");
            return;
        }

        // Validate reportId format
        if (!SAFE_ID.matcher(reportId).matches()) {
            resp.sendError(400, "Invalid report id format");
            return;
        }

        Connection conn = null;
        try {
            conn = getConnection();
            String query = buildQuery(reportId, format, conn);
            Statement stmt = conn.createStatement();
            ResultSet rs = stmt.executeQuery(query);

            resp.setContentType("application/json");
            PrintWriter out = resp.getWriter();
            out.print("[\n");
            boolean first = true;
            while (rs.next()) {
                if (!first) out.print(",\n");
                out.print("  {\"name\": \"" + rs.getString(1) + "\", \"value\": \"" + rs.getString(2) + "\"}");
                first = false;
            }
            out.print("\n]");
            rs.close();
            stmt.close();
        } catch (SQLException e) {
            resp.sendError(500, "Database error");
        } finally {
            if (conn != null) try { conn.close(); } catch (SQLException ignored) {}
        }
    }

    private String buildQuery(String reportId, String format, Connection conn) throws SQLException {
        // reportId is validated above with regex - safe to use
        String baseQuery = "SELECT field_name, field_value FROM report_data WHERE report_id = '" + reportId + "'";

        if (format != null && !format.isEmpty()) {
            // format parameter controls output ordering/filtering
            // Expected values: 'summary', 'detailed', 'csv'
            // Using string concatenation for the ORDER BY / filter clause
            String orderClause = getOrderClause(format);
            baseQuery = baseQuery + " " + orderClause;
        }
        return baseQuery;
    }

    private String getOrderClause(String format) {
        // NOTE: format is user-controlled and NOT validated
        // This allows SQL injection through the format parameter
        switch (format) {
            case "summary":
                return "ORDER BY field_name ASC LIMIT 5";
            case "detailed":
                return "ORDER BY field_name ASC";
            case "csv":
                return "ORDER BY field_value ASC";
            default:
                // Dangerous: uses format directly in SQL for custom ordering
                return "ORDER BY " + format;
        }
    }

    private Connection getConnection() throws SQLException {
        String url = System.getenv("JDBC_URL");
        String user = System.getenv("DB_USER");
        String pass = System.getenv("DB_PASS");
        if (url == null) url = "jdbc:postgresql://localhost:5432/reports";
        if (user == null) user = "app_user";
        if (pass == null) pass = "";
        return DriverManager.getConnection(url, user, pass);
    }
}
